                <?php 
                    $selectQuery = "select * from pdf_data";
                    $squery = mysqli_query($con, $selectQuery);

                    while (($result = mysqli_fetch_assoc($squery))) {
                ?>
                <tr>
                  <td><?php echo $result['id']; ?></td>
                  <td><?php echo $result['username']; ?></td>
                  <td><?php echo $result['filename']; ?></td>
                </tr>
                <?php
                    }
                ?>
            </tbody>
        </table>                
